#import <Foundation/Foundation.h>
#import <Vision/Vision.h>
int main(int argc,const char *argv[]) { @autoreleasepool { NSMutableDictionary *all=[NSMutableDictionary dictionary]; for(int i=1;i<argc;i++){ NSString *path=[NSString stringWithUTF8String:argv[i]]; VNRecognizeTextRequest *req=[VNRecognizeTextRequest new]; req.recognitionLevel=VNRequestTextRecognitionLevelAccurate;req.usesLanguageCorrection=NO;req.usesCPUOnly=YES; NSError *err=nil; [[[VNImageRequestHandler alloc] initWithURL:[NSURL fileURLWithPath:path] options:@{}] performRequests:@[req] error:&err]; if(err) fprintf(stderr,"%s\n",err.description.UTF8String); NSMutableArray *arr=[NSMutableArray array]; for(VNRecognizedTextObservation *r in req.results){ CGRect b=r.boundingBox; [arr addObject:@{@"text":[r topCandidates:1].firstObject.string,@"x":@(b.origin.x),@"y":@(1-b.origin.y-b.size.height),@"w":@(b.size.width),@"h":@(b.size.height)}]; } all[path.lastPathComponent]=arr; } NSData *d=[NSJSONSerialization dataWithJSONObject:all options:NSJSONWritingPrettyPrinted error:nil];puts([[NSString alloc] initWithData:d encoding:NSUTF8StringEncoding].UTF8String); } }
